// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Process liveness
	// (GET /healthz)
	GetLiveness(w http.ResponseWriter, r *http.Request)
	// Dependency readiness
	// (GET /readyz)
	GetReadiness(w http.ResponseWriter, r *http.Request)
	// Progress of an adoption or forget job
	// (GET /v1/admin/adoptions/{jobId})
	GetAdoptionJob(w http.ResponseWriter, r *http.Request, jobId openapi_types.UUID)
	// The agents a speaker can talk through, from Kubernetes and from the panel
	// (GET /v1/admin/agent-profiles)
	ListAgentProfiles(w http.ResponseWriter, r *http.Request)
	// Create an agent profile owned by the panel
	// (POST /v1/admin/agent-profiles)
	CreateAgentProfile(w http.ResponseWriter, r *http.Request)
	// Delete a panel-owned agent profile no speaker uses
	// (DELETE /v1/admin/agent-profiles/{profileId})
	DeleteAgentProfile(w http.ResponseWriter, r *http.Request, profileId AgentProfileId)
	// Change a panel-owned agent profile
	// (PATCH /v1/admin/agent-profiles/{profileId})
	UpdateAgentProfile(w http.ResponseWriter, r *http.Request, profileId AgentProfileId)
	// Forget the stored API key; the agent falls back to its environment
	// (DELETE /v1/admin/agent-profiles/{profileId}/api-key)
	ClearAgentProfileApiKey(w http.ResponseWriter, r *http.Request, profileId AgentProfileId)
	// Store the provider API key of an agent profile (write-only, encrypted at rest)
	// (PUT /v1/admin/agent-profiles/{profileId}/api-key)
	SetAgentProfileApiKey(w http.ResponseWriter, r *http.Request, profileId AgentProfileId)
	// This control room's identity and provisioning defaults
	// (GET /v1/admin/control-room)
	GetControlRoom(w http.ResponseWriter, r *http.Request)
	// The fleet view — known devices joined with what mDNS sees on the LAN
	// (GET /v1/admin/devices)
	ListDevices(w http.ResponseWriter, r *http.Request)
	// One device with its desired config and recent sessions
	// (GET /v1/admin/devices/{deviceId})
	GetDevice(w http.ResponseWriter, r *http.Request, deviceId DeviceId)
	// Rename a device or change the agent it talks through
	// (PATCH /v1/admin/devices/{deviceId})
	UpdateDevice(w http.ResponseWriter, r *http.Request, deviceId DeviceId)
	// Adopt a device over the network (discovered, or by IP)
	// (POST /v1/admin/devices/{deviceId}/adopt)
	AdoptDevice(w http.ResponseWriter, r *http.Request, deviceId DeviceId)
	// Make the unit say something
	// (POST /v1/admin/devices/{deviceId}/announcements)
	CreateAnnouncement(w http.ResponseWriter, r *http.Request, deviceId DeviceId)
	// Clear the desired config
	// (DELETE /v1/admin/devices/{deviceId}/desired-config)
	ClearDesiredConfig(w http.ResponseWriter, r *http.Request, deviceId DeviceId)
	// Set the desired sebastian.config.v1 for a device
	// (PUT /v1/admin/devices/{deviceId}/desired-config)
	SetDesiredConfig(w http.ResponseWriter, r *http.Request, deviceId DeviceId)
	// Set (or clear) the desired device profile
	// (PUT /v1/admin/devices/{deviceId}/desired-profile)
	SetDesiredProfile(w http.ResponseWriter, r *http.Request, deviceId string)
	// Return a device to factory (unadopted) and drop it from the inventory
	// (POST /v1/admin/devices/{deviceId}/forget)
	ForgetDevice(w http.ResponseWriter, r *http.Request, deviceId DeviceId)
	// Ask the unit to record a meeting (RM-03)
	// (POST /v1/admin/devices/{deviceId}/meetings)
	StartMeeting(w http.ResponseWriter, r *http.Request, deviceId DeviceId)
	// Stop the unit's playback
	// (DELETE /v1/admin/devices/{deviceId}/playback)
	StopPlayback(w http.ResponseWriter, r *http.Request, deviceId DeviceId)
	// The playback on for the unit
	// (GET /v1/admin/devices/{deviceId}/playback)
	GetPlayback(w http.ResponseWriter, r *http.Request, deviceId DeviceId)
	// Make the unit play what a source publishes
	// (POST /v1/admin/devices/{deviceId}/playback)
	StartPlayback(w http.ResponseWriter, r *http.Request, deviceId DeviceId)
	// Issue a new per-device secret (shown once)
	// (POST /v1/admin/devices/{deviceId}/secret)
	RegenerateDeviceSecret(w http.ResponseWriter, r *http.Request, deviceId DeviceId)
	// Meetings, newest first (RM-40)
	// (GET /v1/admin/meetings)
	ListMeetings(w http.ResponseWriter, r *http.Request, params ListMeetingsParams)
	// Delete audio and content irreversibly, keeping the trace (RM-46)
	// (DELETE /v1/admin/meetings/{meetingId})
	DeleteMeeting(w http.ResponseWriter, r *http.Request, meetingId MeetingId)
	// One meeting (RM-41)
	// (GET /v1/admin/meetings/{meetingId})
	GetMeeting(w http.ResponseWriter, r *http.Request, meetingId MeetingId)
	// Rename speakers and flag the meeting to keep (RM-31, RM-45)
	// (PATCH /v1/admin/meetings/{meetingId})
	UpdateMeeting(w http.ResponseWriter, r *http.Request, meetingId MeetingId)
	// Stop a meeting (RM-22; the agent uses it for RM-21)
	// (POST /v1/admin/meetings/{meetingId}/stop)
	StopMeeting(w http.ResponseWriter, r *http.Request, meetingId MeetingId)
	// Generate the summary again (RM-32)
	// (POST /v1/admin/meetings/{meetingId}/summarize)
	SummarizeMeeting(w http.ResponseWriter, r *http.Request, meetingId MeetingId)
	// Transcribe again (RM-33)
	// (POST /v1/admin/meetings/{meetingId}/transcribe)
	TranscribeMeeting(w http.ResponseWriter, r *http.Request, meetingId MeetingId)
	// The transcript as a download, txt or srt (RM-41)
	// (GET /v1/admin/meetings/{meetingId}/transcript)
	GetMeetingTranscript(w http.ResponseWriter, r *http.Request, meetingId MeetingId, params GetMeetingTranscriptParams)
	// The desired sebastian.config.v1 document for this device
	// (GET /v1/devices/{deviceId}/config)
	GetDeviceConfig(w http.ResponseWriter, r *http.Request, deviceId string, params GetDeviceConfigParams)
	// Desired device profile for reconciliation polls
	// (GET /v1/devices/{deviceId}/desired-profile)
	GetDesiredProfile(w http.ResponseWriter, r *http.Request, deviceId string, params GetDesiredProfileParams)
	// Challenge for a device to enrol with the organization secret
	// (GET /v1/devices/{deviceId}/enroll)
	GetEnrollmentChallenge(w http.ResponseWriter, r *http.Request, deviceId DeviceId)
	// Enrol a device that proves it holds the organization secret
	// (POST /v1/devices/{deviceId}/enroll)
	EnrollDevice(w http.ResponseWriter, r *http.Request, deviceId DeviceId)
	// The unit confirms it records, or that it stopped and why (RM-52)
	// (PUT /v1/devices/{deviceId}/meeting)
	ReportMeeting(w http.ResponseWriter, r *http.Request, deviceId DeviceId, params ReportMeetingParams)
	// The unit asks for a meeting after the MUTE gesture (RM-02)
	// (POST /v1/devices/{deviceId}/meetings)
	RequestMeeting(w http.ResponseWriter, r *http.Request, deviceId DeviceId, params RequestMeetingParams)
	// The device reports the configuration it runs (RF-42)
	// (PUT /v1/devices/{deviceId}/running-config)
	ReportRunningConfig(w http.ResponseWriter, r *http.Request, deviceId DeviceId, params ReportRunningConfigParams)
	// Create a device session and dispatch its assigned agent
	// (POST /v1/sessions)
	CreateSession(w http.ResponseWriter, r *http.Request, params CreateSessionParams)
}

